import * as React from "react";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

export type LumenCardProps = React.ComponentProps<typeof Card> & {
  tone?: "theme" | "ember" | "lagoon" | "lilac";
};

export const LumenCard = React.forwardRef<HTMLDivElement, LumenCardProps>(function LumenCard({ className, tone = "theme", ...props }, ref) {
  return (
    <Card
      {...props}
      ref={ref}
      data-lumen-tone={tone}
      className={cn("lumenmorph lumenmorph-border lumenmorph-theme", className)}
    />
  );
});

import * as React from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export type LumenButtonProps = React.ComponentProps<typeof Button> & {
  tone?: "theme" | "ember" | "lagoon" | "lilac";
};

export const LumenButton = React.forwardRef<HTMLButtonElement, LumenButtonProps>(function LumenButton({ className, tone = "theme", variant = "outline", ...props }, ref) {
  return (
    <Button
      {...props}
      ref={ref}
      variant={variant}
      data-lumen-tone={tone}
      className={cn("lumenmorph lumenmorph-border lumenmorph-theme", className)}
    />
  );
});

"use client";

import { useEffect } from "react";
import { trackPointer } from "@monabbous/lumenmorph";

/** Mount once in your app layout. Cards and buttons remain usable without it. */
export function LumenPointer({ smooth = true }: { smooth?: boolean }) {
  useEffect(() => {
    const owner = document.documentElement;
    const hadMotion = owner.classList.contains("lumenmorph-motion");
    if (smooth && !hadMotion) owner.classList.add("lumenmorph-motion");
    const stop = trackPointer(owner);
    return () => {
      stop();
      if (smooth && !hadMotion) owner.classList.remove("lumenmorph-motion");
    };
  }, [smooth]);
  return null;
}
